def get_all_valid_edge_sets(N, k):
    # A set of edges E = {(S_1, B_1), ..., (S_k, B_k)}
    # such that S_1 < S_2 < ... < S_k
    # and B_1 < B_2 < ... < B_k
    # and S_i < B_i for all i
    # S_i, B_i \in {1, ..., N}

    # This can be represented as a sequence of pairs (S_1, B_1), ..., (S_k, B_k)
    # such that 1 <= S_1 < S_2 < ... < S_k <= N
    # and 1 <= B_1 < B_2 < ... < B_k <= N
    # and S_i < B_i for all i.

    # We can generate all such sets.
    # To avoid duplicates, we can use the fact that the pairs are ordered.
    # Let's use a recursive approach.

    valid_sets = []

    def backtrack(current_edges):
        if len(current_edges) == k:
            valid_sets.append(list(current_edges))
            return

        last_S = current_edges[-1][0] if current_edges else 0
        last_B = current_edges[-1][1] if current_edges else 0

        for s in range(last_S + 1, N + 1):
            for b in range(last_B + 1, N + 1):
                if s < b:
                    backtrack(current_edges + [(s, b)])

    backtrack([])
    return valid_sets

def get_reachable_pairs(edges):
    adj = {}
    for u, v in edges:
        if u not in adj: adj[u] = set()
        adj[u].add(v)

    reachable = set()
    for u, v in edges:
        stack = [u]
        visited = set()
        while stack:
            curr = stack.pop()
            if curr in adj:
                for neighbor in adj[curr]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        stack.append(neighbor)
        reachable.update(visited)
    return reachable

def find_smallest_k(N):
    for k in range(1, N + 1):
        valid_sets = get_all_valid_edge_sets(N, k)
        # Reachable pairs for each valid set
        reachable_sets = [get_reachable_pairs(edge_set) for edge_set in valid_sets]

        # Check if there exist two reachable sets P_A, P_B such that P_A \cap P_B = empty
        found_empty_intersection = False
        for i in range(len(reachable_sets)):
            for j in range(i, len(reachable_sets)):
                if reachable_sets[i].isdisjoint(reachable_sets[j]):
                    found_empty_intersection = True
                    break
            if found_empty_intersection:
                break

        if not found_empty_intersection:
            return k
    return None

