import itertools

def get_connections(edges):
    connections = set()
    adj = {}
    for s, b in edges:
        if s not in adj:
            adj[s] = []
        adj[s].append(b)

    nodes = sorted(list(set([s for s, b in edges] + [b for s, b in edges])))
    for start_node in nodes:
        if start_node in adj:
            visited = {start_node}
            queue = [start_node]
            while queue:
                u = queue.pop(0)
                if u in adj:
                    for v in adj[u]:
                        if v not in visited:
                            visited.add(v)
                            queue.append(v)
            for v in visited:
                if v > start_node:
                    connections.add((start_node, v))
    return connections

def get_all_possible_edge_sets(N, k):
    possible_edge_sets = []
    for S in itertools.combinations(range(1, N + 1), k):
        for B in itertools.combinations(range(1, N + 1), k):
            if all(S[i] < B[i] for i in range(k)):
                possible_edge_sets.append(list(zip(S, B)))
    return possible_edge_sets

def solve_for_N(N):
    for k in range(1, N + 1):
        edge_sets = get_all_possible_edge_sets(N, k)
        connection_sets = [get_connections(es) for es in edge_sets]

        exists_disjoint = False
        for i in range(len(connection_sets)):
            for j in range(i + 1, len(connection_sets)):
                if connection_sets[i].isdisjoint(connection_sets[j]):
                    exists_disjoint = True
                    break
            if exists_disjoint:
                break

        if not exists_disjoint:
            return k
    return None

for n in range(3, 11):
    print(f"N={n}, k={solve_for_N(n)}")

