def get_reachability(edges):
    # edges is a list of (s_i, b_i)
    # Reachability set S = {(u, v) | u < v and v is reachable from u}
    reachability = set()
    # Since it's a DAG, we can use Floyd-Warshall or just BFS/DFS from each node
    # But k is small, and edges are few.
    # Each edge (s_i, b_i) means s_i -> b_i
    # Let's just find all reachable pairs.
    adj = {}
    for u, v in edges:
        if u not in adj: adj[u] = []
        adj[u].append(v)

    nodes = sorted(list(set([u for u, v in edges] + [v for u, v in edges])))
    for start_node in nodes:
        # BFS to find all reachable nodes
        visited = {start_node}
        queue = [start_node]
        while queue:
            u = queue.pop(0)
            if u in adj:
                for v in adj[u]:
                    if v not in visited:
                        visited.add(v)
                        queue.append(v)
        for end_node in visited:
            if start_node < end_node:
                reachability.add((start_node, end_node))
    return reachability

def solve_for_N(N):
    for k in range(1, N + 1):
        edges_list = get_valid_edges(N, k)
        reachability_sets = [get_reachability(e) for e in edges_list]

        # Check if there exist two sets S1, S2 such that S1 \cap S2 = empty
        found_disjoint = False
        for i in range(len(reachability_sets)):
            for j in range(i + 1, len(reachability_sets)):
                if reachability_sets[i].isdisjoint(reachability_sets[j]):
                    found_disjoint = True
                    break
            if found_disjoint:
                break

        if not found_disjoint:
            return k
    return None

