    # s_1 < s_2 < ... < s_k, b_1 < b_2 < ... < b_k, s_j < b_j
    all_sets = set()
    # s_j are k distinct values from {1, ..., N}
    # b_j are k distinct values from {1, ..., N}
    # But there's more: s_j < b_j for all j.
    # And s_1 < s_2 < ... < s_k and b_1 < b_2 < ... < b_k.

    # Let's iterate over all possible sets of s_j and b_j.
    for s_indices in itertools.combinations(range(1, N + 1), k):
        s = list(s_indices)
        for b_indices in itertools.combinations(range(1, N + 1), k):
            b = list(b_indices)
            # Check s_j < b_j for all j
            if all(s[j] < b[j] for j in range(k)):
                # This is a valid set of edges
                edges = []
                for j in range(k):
                    edges.append((s[j], b[j]))

                # Compute transitive closure
                # Since it's a set of paths, we can just find the paths.
                adj = {}
                for u, v in edges:
                    if u not in adj: adj[u] = []
                    adj[u].append(v)

                connections = set()
                for start_node in range(1, N + 1):
                    # BFS/DFS to find all reachable nodes
                    stack = [start_node]
                    visited = {start_node}
                    while stack:
                        u = stack.pop()
                        if u in adj:
                            for v in adj[u]:
